comp = {"A":"T","T":"A","G":"C","C":"G"}
def rc(s): return "".join(comp[c] for c in reversed(s))

# Find inverted repeats: look for a sequence and its reverse complement nearby
def find_IRs(s, min_len=12, max_len=40):
    hits=[]
    n=len(s)
    for L in range(min_len, max_len+1):
        seen={}
        for i in range(n-L+1):
            sub=s[i:i+L]
            rcsub=rc(sub)
            if rcsub in seen:
                pass
        # simpler: compare all pairs
    # brute force with hashing of revcomp
    for L in range(max_len, min_len-1, -1):
        d={}
        for i in range(n-L+1):
            sub=s[i:i+L]
            if sub not in d:
                d[sub]=i
        for i in range(n-L+1):
            sub=s[i:i+L]
            r=rc(sub)
            if r in d and d[r]!=i:
                j=d[r]
                if j>i:
                    hits.append((L,i,j))
    return hits

hits = find_IRs(seq, 12, 40)
