def stopfree(s, strand, min_nt=200):
    out=[]
    for fr in range(3):
        start=fr
        cur=""
        pos=fr
        # walk codons
        j=fr
        seg_start=fr
        while j+3<=len(s):
            cod = s[j:j+3]
            if codon[cod]=="*":
                L=j-seg_start
                if L>=min_nt:
                    out.append((strand,fr,seg_start,j,L,s[seg_start:j]))
                seg_start=j+3
            j+=3
        L=j-seg_start
        if L>=min_nt:
            out.append((strand,fr,seg_start,j,L,s[seg_start:j]))
    return out

